def seek(self, index):
    self._index = index
    remainder = index - len(self._cache)
    if remainder > 0:
        consume(self, remainder)

def relative_seek(self, offset):
    if self._index is None:
        # Need to consume up to current position
        self._index = len(self._cache)
    new_index = self._index + offset
    if new_index < 0:
        raise ValueError('cannot seek before start')
    self.seek(new_index)
